To solve this problem, we need to generate a unified diff between two lists of lines using the longest common subsequence (LCS) algorithm. The unified diff should include context lines around changes and merge overlapping hunks. Edge cases include when the input lists are identical, when there are no changes, and when the entire list is added or removed. We will use dynamic programming to find the LCS and then construct the diff based on the LCS and the specified context.

ANSWER:
```python
def unified_diff(a, b, context=3):
    def lcs(X, Y):
        m = len(X)
        n = len(Y)
        L = [[0] * (n + 1) for i in range(m + 1)]
        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0 or j == 0:
                    L[i][j] = 0
                elif X[i - 1] == Y[j - 1]:
                    L[i][j] = L[i - 1][j - 1] + 1
                else:
                    L[i][j] = max(L[i - 1][j], L[i][j - 1])
        return L

    def backtrack(L, X, Y, i, j):
        if i == 0 or j == 0:
            return []
        elif X[i - 1] == Y[j - 1]:
            return backtrack(L, X, Y, i - 1, j - 1) + [X[i - 1]]
        elif L[i - 1][j] > L[i][j - 1]:
            return backtrack(L, X, Y, i - 1, j)
        else:
            return backtrack(L, X, Y, i, j - 1)

    def generate_hunks(a, b, lcs_lines, context=3):
        a_index = 0
        b_index = 0
        hunks = []
        while a_index < len(a) or b_index < len(b):
            while a_index < len(a) and a[a_index] not in lcs_lines:
                a_index += 1
            while b_index < len(b) and b[b_index] not in lcs_lines:
                b_index += 1
            if a_index >= len(a) and b_index >= len(b):
                break
            a_start = a_index + 1
            b_start = b_index + 1
            a_lines = []
            b_lines = []
            while a_index < len(a) and a[a_index] in lcs_lines:
                a_lines.append(a[a_index])
                a_index += 1
            while b_index < len(b) and b[b_index] in lcs_lines:
                b_lines.append(b[b_index])
                b_index += 1
            a_len = len(a_lines)
            b_len = len(b_lines)
            a_context = []
            b_context = []
            for k in range(context):
                if a_index + k < len(a) and a[a_index + k] not in lcs_lines:
                    a_context.append(a[a_index + k])
                if b_index + k < len(b) and b[b_index + k] not in lcs_lines:
                    b_context.append(b[b_index + k])
            a_len += len(a_context)
            b_len += len(b_context)
            hunk = ['@@ -{},{} +{},{} @@'.format(a_start, a_len, b_start, b_len)]
            for line in a_lines:
                hunk.append(' ' + line)
            for line in a_context:
                hunk.append('-' + line)
            for line in b_lines:
                hunk.append('+' + line)
            for line in b_context:
                hunk.append('+' + line)
            hunks.append(hunk)
        return hunks

    if a == b:
        return []

    L = lcs(a, b)
    lcs_lines = backtrack(L, a, b, len(a), len(b))
    hunks = generate_hunks(a, b, lcs_lines, context)
    return [line for hunk in hunks for line in hunk]
```

