def deep_copy(obj):
    seen = {}

    def _deep_copy(o):
        if id(o) in seen:
            return seen[id(o)]
        if isinstance(o, (str, int, float, bool, type(None))):
            return o
        if isinstance(o, dict):
            copy = {}
            seen[id(o)] = copy
            for k, v in o.items():
