To achieve the desired functionality, we need to create a Proxy that recursively wraps nested objects and arrays. This ensures that any changes to properties, including those within deeply nested structures, trigger the `onChange` callback. Additionally, we must handle special cases like array mutations (e.g., `push`) and ensure that writes that do not change the value (using SameValueZero comparison) do not trigger the callback. We also need to return proxies for objects and the plain values for primitives when reading properties.

ANSWER:

```javascript
function observe(target, onChange) {
  const handler = {
    get(obj, prop) {
      if (typeof obj[prop] === 'object' && obj[prop] !== null) {
        return new Proxy(obj[prop], handler);
      }
      return obj[prop];
    },
    set(obj, prop, value) {
      const oldValue = obj[prop];
      if (!Object.is(value, oldValue)) {
        obj[prop] = value;
        onChange([prop], value, oldValue);
        if (Array.isArray(obj) && typeof prop === 'number') {
          onChange([prop], value, oldValue);
        }
        return true;
      }
      return false;
    },
    deleteProperty(obj, prop) {
      if (obj.hasOwnProperty(prop)) {
        const oldValue = obj[prop];
        delete obj[prop];
        onChange([prop], undefined, oldValue);
        return true;
      }
      return false;
    }
  };

  return new Proxy(target, handler);
}

module.exports = observe;
```

