hjs-014.text:
To implement a Redux-like store with the specified features, we need to carefully manage the state transitions, action dispatching, and subscription notifications. One key challenge is ensuring that subscriptions made during a notification do not trigger immediately, and that unsubscriptions prevent future calls. Additionally, we must handle dispatching from within subscribers correctly, allowing them to complete before resuming the outer notification loop.

ANSWER:

```javascript
function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];

  function getState() {
    return state;
  }

  function dispatch(action) {
    if (typeof action !== 'object' || action === null) {
      throw new Error('Actions must be plain objects.');
    }
    if (typeof action.type === 'undefined') {
      throw new Error('Actions may not have an undefined "type" property.');
    }

    const currentState = state;
    state = reducer(currentState, action);

    // Snapshot the current listeners to avoid side effects during iteration
    const currentListeners = listeners.slice();
    for (let i = 0; i < currentListeners.length; i++) {
      currentListeners[i]();
    }
  }

  function subscribe(fn) {
    if (typeof fn !== 'function') {
      throw new Error('Expected the listener to be a function.');
    }

    listeners.push(fn);

    let isSubscribed = true;

    return function unsubscribe() {
      if (!isSubscribed) {
        return;
      }

      isSubscribed = false;
      const index = listeners.indexOf(fn);
      listeners.splice(index, 1);
    };
  }

  return {
    getState,
    dispatch,
    subscribe
  };
}

module.exports = createStore;
```

