To handle the conversion between a query string and a JavaScript object, we need to parse the query string into an object that can represent arrays and nested structures using bracket notation. This involves decoding percent-encoded characters and handling special cases like repeated keys and keys without values. When building the query string from an object, we must ensure that arrays and nested objects are correctly represented using bracket notation, and that all characters are properly percent-encoded. Additionally, we need to sort the keys to maintain consistency.

Edge cases include handling of empty strings, repeated keys, and ensuring that the conversion process is reversible, meaning that `parseQuery(buildQuery(obj))` should return an object structurally identical to `obj`.

ANSWER:

```javascript
function parseQuery(qs) {
    const obj = {};
    qs = qs.replace(/^\?/, '');
    qs.split('&').forEach(pair => {
        const [key, value] = pair.split('=');
        const decodedKey = decodeURIComponent(key || '');
        const decodedValue = decodeURIComponent(value || '').replace(/\+/g, ' ');
        const keys = decodedKey.match(/[^[\]]+|\[(.*?)\]/g).map(k => k.replace(/^'(.*)'$/, '$1'));
        let target = obj;
        for (let i = 0; i < keys.length - 1; i++) {
            if (!target[keys[i]]) {
                target[keys[i]] = isNaN(keys[i + 1]) ? {} : [];
            }
            target = target[keys[i]];
        }
        const lastKey = keys[keys.length - 1];
        if (target[lastKey] === undefined) {
            target[lastKey] = decodedValue;
        } else if (Array.isArray(target[lastKey])) {
            target[lastKey].push(decodedValue);
        } else {
            target[lastKey] = [target[lastKey], decodedValue];
        }
    });
    return obj;
}

function buildQuery(obj) {
    function build(params, prefix) {
        return Object.keys(params)
            .sort()
            .map(key => {
                const value = params[key];
                const encodedKey = encodeURIComponent(prefix ? `${prefix}[${encodeURIComponent(key)}]` : key);
                if (typeof value === 'object' && value !== null) {
                    return build(value, encodedKey);
                } else {
                    return `${encodedKey}=${encodeURIComponent(value || '')}`;
                }
            })
            .join('&');
    }
    return build(obj, '');
}

module.exports = { parseQuery, buildQuery };
```

